#include "../src/services/titan_disc_service.h"
#include <assert.h>
#include <stdio.h>
#include <string.h>
uint64_t TitanTime_NowMilliseconds(void){static uint64_t t=100;return ++t;}
int TitanNotifications_Push(int k,const char*t,const char*m){(void)k;(void)t;(void)m;return 1;}
void TitanDiagnostics_Event(int l,int s,uint16_t e,int32_t r,uint32_t a,uint32_t b,uint32_t c,uint32_t d){(void)l;(void)s;(void)e;(void)r;(void)a;(void)b;(void)c;(void)d;}
typedef struct Fake { int phase; } Fake;
static int probe(void *c,TitanDiscMediaType*m){Fake*f=c;if(f->phase==0){*m=TITAN_DISC_MEDIA_NONE;return 0;}if(f->phase==1){*m=TITAN_DISC_MEDIA_PS2_DVD;return 1;}if(f->phase==2){*m=TITAN_DISC_MEDIA_UNSUPPORTED;return 1;}return -1;}
static int metadata(void*c,const char*id,char*b,size_t n){(void)c;(void)id;const char*s="title=Cached Disc Title\nicon=mass:/TITAN/cache/disc/icon.timg\nbackground=mass:/TITAN/cache/disc/bg.timg\nigr_profile=100\n";if(strlen(s)+1>n)return -1;strcpy(b,s);return (int)strlen(s);}
static int cnf(void*c,char*b,size_t n){(void)c;const char*s="BOOT2 = cdrom0:\\SLUS_123.45;1\r\nVER = 1.00\nVMODE=NTSC\n"; if(strlen(s)+1>n)return -1;strcpy(b,s);return (int)strlen(s);}
int main(void){TitanDiscInfo i;char p[128],id[24];Fake f={0};TitanDiscPlatformOps ops={probe,cnf,metadata};memset(&i,0,sizeof(i));assert(TitanDisc_ParseSystemCnf(" boot2=cdrom0:\\SLES_543.21;1\nver=2.00\n",47,&i));assert(!strcmp(i.title_id,"SLES_543.21"));assert(i.region==TITAN_DISC_REGION_PAL);assert(TitanDisc_NormalizeBootPath("SLPM_111.22",p,sizeof(p)));assert(!strcmp(p,"cdrom0:\\SLPM_111.22;1"));assert(TitanDisc_ExtractTitleId(p,id,sizeof(id)));assert(i.system_cnf_valid);TitanDiscService_SetPlatformOps(&ops,&f);TitanDiscService_Initialize();TitanDiscService_UpdateMainThread(1000);assert(TitanDiscService_HasStorageWork());assert(TitanDiscService_StorageWorkerPump());TitanDiscService_UpdateMainThread(1001);assert(TitanDiscService_GetInfo()->state==TITAN_DISC_NO_MEDIA);f.phase=1;TitanDiscService_UpdateMainThread(2000);assert(TitanDiscService_StorageWorkerPump());TitanDiscService_UpdateMainThread(2001);assert(TitanDiscService_IsReady());assert(!strcmp(TitanDiscService_GetInfo()->title_id,"SLUS_123.45"));assert(!strcmp(TitanDiscService_GetInfo()->title,"Cached Disc Title"));assert(TitanDiscService_GetInfo()->metadata_state==TITAN_DISC_METADATA_LOCAL_CACHE);assert(TitanDiscService_GetInfo()->compatibility_profile_hint==100u);{unsigned int g=TitanDiscService_GetInfo()->media_generation;TitanDiscService_UpdateMainThread(2800);assert(TitanDiscService_StorageWorkerPump());TitanDiscService_UpdateMainThread(2801);assert(TitanDiscService_GetInfo()->media_generation==g);}f.phase=0;TitanDiscService_UpdateMainThread(3600);assert(TitanDiscService_StorageWorkerPump());TitanDiscService_UpdateMainThread(3601);assert(TitanDiscService_GetInfo()->state==TITAN_DISC_EJECTED);puts("buildfix30-disc-service-host: OK");return 0;}
